import React from "react";
import "./BudgetLimits.css";

function BudgetLimits({
  incomeCategory,
  questionnaire,
  spendingPriorities,
  budgetLimits = {},   // ✅ FIX: default empty object
  setBudgetLimits,
  onNext
}) {

  const handleChange = (category, value) => {
    setBudgetLimits({
      ...budgetLimits,
      [category]: value
    });
  };

  return (
    <div className="budget-container">
      <h2>Set Your Monthly Budget Limits</h2>

      <div className="budget-item">
        <label>Food & Groceries</label>
        <input
          type="number"
          value={budgetLimits["Food & Groceries"] || ""}  // ✅ SAFE
          onChange={(e) =>
            handleChange("Food & Groceries", e.target.value)
          }
        />
      </div>

      <div className="budget-item">
        <label>Bills</label>
        <input
          type="number"
          value={budgetLimits["Bills"] || ""}
          onChange={(e) =>
            handleChange("Bills", e.target.value)
          }
        />
      </div>

      <div className="budget-item">
        <label>Shopping</label>
        <input
          type="number"
          value={budgetLimits["Shopping"] || ""}
          onChange={(e) =>
            handleChange("Shopping", e.target.value)
          }
        />
      </div>

      <div className="budget-item">
        <label>Transport</label>
        <input
          type="number"
          value={budgetLimits["Transport"] || ""}
          onChange={(e) =>
            handleChange("Transport", e.target.value)
          }
        />
      </div>

      <button
        className="save-btn"
        onClick={() => onNext(budgetLimits)}   // ✅ FINAL FLOW
      >
        Save Limits
      </button>
    </div>
  );
}

export default BudgetLimits;
